// scenario: cart-eco-threshold · sha256:f5ce2ce0910463f9fe94abdf243fee6651770f4d56c23a64e9ce12281feb5cf1
// request: Add a Wood Saw, then two units of the first available product. Raise the saw to three units, then remove the other product. Check after each change that the eco discount applies exactly when more than half of the units are rated A or B, and that the total is correct.
// body-sha256: 491418bd3cfa8ca026632756cb581ca49ca3b654c206137cb2d7cb6cb52b78fc
import { test } from '../support/core/fixtures';

test.use({ preconditions: ['empty-cart', 'guest', 'no-geolocation'], priceSource: 'ui', reserved: ['Wood Saw'] });

test('Eco discount follows the share of A- or B-rated units through add, quantity change and remove', async ({ shopper }) => {
  const a = await shopper.add({ pick: 'by-name', name: 'Wood Saw' }, 1);
  await shopper.checkTotal('S1');

  const b = await shopper.add({ pick: 'first-available', filters: { needQty: 2 } }, 2);
  await shopper.checkTotal('S2');

  await shopper.setQuantity(a, 3);
  await shopper.checkTotal('S3');

  await shopper.remove(b);
  await shopper.checkTotal('S4');
});
